# Full old unit destination map, including narrative rules, not just numeric rows.
def safe(x):return str(x).replace('|','\\|').replace('\n',' ')
for slug in [p,f]:
 rr=rows[slug];out=[f'# {slug}: full figure and rule ledger',f'Read date: {day}. Writer evidence, not an independent review. Quotes are exact short excerpts from retained official raw bodies and derivative native-LF readers. Ellipses are editorial truncations. Each compound row records one named rule or computation with all stated parameters; illustrative inputs/results are arithmetic, not statutory amounts. Selected scopes below are reads, not acquisition-only claims. Existing source dates and historical partial-review statements stay in the Guide.','| # | Guide section | Figure / rule as written | Source (act/article or page), reader locator | URL | Exact quote (original language) | Read on |','|---|---|---|---|---|---|---|']
 for i,row in enumerate(rr,1):out.append('| '+ ' | '.join(map(safe,[i,*row]))+' |')
 out+=['','## Old topics carried','The original main topics are mapped at paragraph/table-row granularity. Unchanged text retains its original unit. New methods replace only the named former reservations; precise remaining branches stay in Sources.','| Original unit | Old topic, verbatim | Current destination |','|---|---|---|']
 base=(r/'baselines'/f'{slug}.original.txt').read_text();cur=(d/f'{slug}.md').read_text();section='metadata';fence=False;num=0
 for line in base.splitlines():
  if line.startswith('## '):section=line[3:]
  if line.startswith('```'):fence=not fence;continue
  if fence or not line.strip()or line.startswith(('#','[','---','<!--')) or section in ['metadata','Talk to a verified accountant']:continue
  if line.startswith('|---')or line.startswith('| Source |'):continue
  if line.startswith(('name:','description:','version:','jurisdiction:','tax_year:','last_updated:','authored_by:','review_status:','trust_label:','category:','tier:','license:')):continue
  num+=1;dest=section+'; exact text retained'if line in cur else section+'; expanded or narrowed in place, see exact replacement ledger'
  if line.startswith('Not yet confirmed:'):dest='Sources; named residuals retained, positive new methods in Base/Capital'
  out.append('| '+ ' | '.join(map(safe,[num,line,dest]))+' |')
 (r/'ledgers'/f'{slug}.md').write_text('\n'.join(out)+'\n')
